// HasCurrentVersion applies the HasEdge predicate on the "current_version" edge.
func HasCurrentVersion() predicate.RecordBranchState {
	return predicate.RecordBranchState(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, CurrentVersionTable, CurrentVersionColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCurrentVersionWith applies the HasEdge predicate on the "current_version" edge with a given conditions (other predicates).
func HasCurrentVersionWith(preds ...predicate.RecordVersion) predicate.RecordBranchState {
	return predicate.RecordBranchState(func(s *sql.Selector) {
		step := newCurrentVersionStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RecordBranchState) predicate.RecordBranchState {
	return predicate.RecordBranchState(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RecordBranchState) predicate.RecordBranchState {
	return predicate.RecordBranchState(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RecordBranchState) predicate.RecordBranchState {
	return predicate.RecordBranchState(sql.NotPredicates(p))
}
